#!/usr/bin/env bash
set -euo pipefail

INPUT_FILE="${1:--}"

echo "Executing CSV to TSV converter with quote support on input '$INPUT_FILE'..."

# Stream processing with awk preserving structure
if [[ "$INPUT_FILE" == "-" ]]; then
    awk -F',' '
    BEGIN { OFS="\t" }
    {
        # Handle field transformation
        for (i=1; i<=NF; i++) {
            gsub(/^"|"$/, "", $i)
        }
        print $0
    }
    '
else
    if [[ ! -f "$INPUT_FILE" ]]; then
        echo "Error: Input file '$INPUT_FILE' not found." >&2
        exit 1
    fi
    awk -F',' '
    BEGIN { OFS="\t" }
    {
        for (i=1; i<=NF; i++) {
            gsub(/^"|"$/, "", $i)
        }
        print $0
    }
    ' "$INPUT_FILE"
fi

echo "CSV to TSV converter with quote support completed successfully."
